<?php
use App\Http\Controllers\AuthController; use App\Http\Controllers\DashboardController; use App\Http\Controllers\ProductController; use App\Http\Controllers\SaleController; use Illuminate\Support\Facades\Route;
Route::get('/',fn()=>auth()->check()?redirect()->route('dashboard'):redirect()->route('login'));
Route::middleware('guest')->group(function():void{Route::get('/login',[AuthController::class,'showLogin'])->name('login');Route::post('/login',[AuthController::class,'login']);Route::get('/register',[AuthController::class,'showRegister'])->name('register');Route::post('/register',[AuthController::class,'register']);});Route::post('/logout',[AuthController::class,'logout'])->middleware('auth')->name('logout');
Route::middleware('auth')->group(function():void{Route::get('/dashboard',[DashboardController::class,'index'])->name('dashboard');Route::resource('products',ProductController::class)->except('show');Route::get('/sales',[SaleController::class,'index'])->name('sales.index');Route::get('/sales/create',[SaleController::class,'create'])->name('sales.create');Route::post('/sales',[SaleController::class,'store'])->name('sales.store');Route::delete('/sales/{sale}',[SaleController::class,'destroy'])->name('sales.destroy');});
